function loadLocalEnv() {
  const envPaths = [
    process.env.DESKTOP_ENV_PATH,
    fileURLToPath(new URL(".env", import.meta.url)),
  ].filter(Boolean);

  for (const envPath of envPaths) {
    if (!existsSync(envPath)) continue;
    const content = readFileSync(envPath, "utf8");
    for (const line of content.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1).trim().replace(/^['"]|['"]$/g, "");
      if (key && process.env[key] === undefined) {
        process.env[key] = value;
      }
    }
  }
}

function resolvePublicDir() {
  const candidates = [
    join(MODULE_DIR, "public"),
    join(process.cwd(), "public"),
    resolve(MODULE_DIR, "..", "public"),
    resolve(process.cwd(), "..", "public"),
    join(process.cwd(), "app", "public"),
    join(MODULE_DIR, "app", "public"),
  ];
  for (const candidate of candidates) {
    if (existsSync(join(candidate, "index.html"))) {
      return candidate;
    }
  }
  console.warn(`public/index.html not found. Tried: ${candidates.join(" | ")}`);
  return join(MODULE_DIR, "public");
}

function setStaticNoCacheHeaders(res) {
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, proxy-revalidate");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");
}

function sendEmbeddedStaticAsset(assetPath, res, next) {
  const asset = EMBEDDED_STATIC_ASSETS.get(assetPath);
  if (!asset) {
    if (typeof next === "function") return next();
    res.status(404).send("Not found");
    return;
  }
  setStaticNoCacheHeaders(res);
  res.type(asset.type);
  res.send(Buffer.from(asset.base64, "base64").toString("utf8"));
}

function sendAppStaticAsset(assetPath, res, next) {
  const normalizedPath = assetPath === "/" ? "/index.html" : assetPath;
  const diskPath = join(PUBLIC_DIR, normalizedPath.replace(/^\/+/, ""));
  setStaticNoCacheHeaders(res);
  if (existsSync(diskPath)) {
    res.sendFile(diskPath, (error) => {
      if (error && !res.headersSent) {
        sendEmbeddedStaticAsset(normalizedPath, res, next);
      }
    });
    return;
  }
  sendEmbeddedStaticAsset(normalizedPath, res, next);
}

