app.get("/api/forecasts", async (req, res) => {
  try {
    const competitionId = normalizeCompetitionId(req.query.competition || "PL");
    const season = Number(req.query.season || currentEuropeanSeason());
    const data = await getFiveLeagueData({ competitionId, season, status: "all" });
    const nowMs = Date.now();
    const pastDays = Number(req.query.pastDays ?? 21);
    const futureDays = Number(req.query.futureDays ?? 21);
    const window = data.matches.filter((match) => {
      const kickoff = Date.parse(match.kickoffUtc || "");
      return Number.isFinite(kickoff) && kickoff >= nowMs - pastDays * 86400000 && kickoff <= nowMs + futureDays * 86400000;
    });
    const items = {};
    for (const match of window) {
      const forecast = await forecastService.forecast({ match, liveMatches: data.matches }).catch(() => null);
      if (!forecast) continue;
      items[match.id] = {
        probabilities: { home: forecast.probabilities.home, draw: forecast.probabilities.draw, away: forecast.probabilities.away, over25: forecast.probabilities.over25 },
        expectedGoals: forecast.expectedGoals,
        pick: forecast.pick,
        score: forecast.headlineScore.score,
        confidence: forecast.confidence,
        hasMarket: Boolean(forecast.market),
        ranks: { home: forecast.ratings.home.rank, away: forecast.ratings.away.rank },
      };
    }
    res.json({ refreshedAt: new Date().toISOString(), competitionId, season, items });
  } catch (error) {
    res.status(502).json(errorPayload(error, "批量预测失败"));
  }
});

