app.get("/api/analyze", async (req, res) => {
  try {
    const matchId = String(req.query.matchId || "");
    const oddsKey = String(req.query.oddsKey || process.env.ODDS_API_KEY || "").trim();
    const quick = req.query.quick === "1";
    const prefetch = req.query.prefetch === "1";
    const depth = String(req.query.depth || "balanced").toLowerCase();
    const competitionId = normalizeCompetitionId(req.query.competition || "");
    const season = Number(req.query.season || currentEuropeanSeason());
    let data = await getFiveLeagueData({ competitionId, season });
    let match = matchId ? findMatchByAnyId(data.matches, matchId) : data.matches[0];
    if (!match && matchId) {
      const resolved = await leagueDataService.findMatch(matchId).catch(() => null);
      if (resolved?.competitionId === competitionId && Number(resolved?.season) === season) {
        match = resolved;
        data = { ...data, matches: [match, ...data.matches] };
      }
    }
    if (!match && matchId) {
      res.status(404).json({
        message: "没有找到该场比赛",
        detail: `当前赛程源暂未返回 matchId=${matchId}。请刷新赛程后重试，系统不会再错误退回到第一场比赛。`,
      });
      return;
    }
    if (!matchId) match = match || data.matches[0];

    if (!match) {
      res.status(404).json({ message: "没有找到可分析的比赛" });
      return;
    }

    const analysisModeKey = quick ? "quick" : `full:${depth}`;
    const calibrationCacheKey = scoreCalibrationState.profile?.available
      ? `cal:${scoreCalibrationState.sample}:${scoreCalibrationState.refreshedAt}`
      : "cal:none";
    const analysisCacheKey = `analysis:${analysisModeKey}:${match.id}:${oddsKey ? "odds" : "no-odds"}:${calibrationCacheKey}`;
    const payload = await cached(analysisCacheKey, quick ? 8 * 60 * 1000 : 5 * 60 * 1000, async () => {
      const venue = resolveMatchVenue(match);
      match = { ...match, stadium: venue };
      const geo = quick
        ? venueGeoFallback(venue) || fallbackGeo(venue, { message: "快速模式使用场馆兜底定位" })
        : await geocodeVenue(venue).catch((error) => fallbackGeo(venue, error));
      const weatherDateInfo = match.venueDateInfo || match.dateInfo;
      const [standings, previousStandings, homeRecent, awayRecent] = await Promise.all([
        leagueDataService.getStandings({ competitionId: match.competitionId, season: match.season })
          .catch((error) => ({ available: false, tables: {}, message: error.message })),
        leagueDataService.getStandings({ competitionId: match.competitionId, season: Number(match.season) - 1 })
          .catch(() => ({ available: false, tables: {} })),
        leagueDataService.getTeamRecentMatches({ competitionId: match.competitionId, teamId: match.home?.footballDataId || match.home?.id, before: match.kickoffUtc, limit: 10 })
          .catch(() => ({ matches: [] })),
        leagueDataService.getTeamRecentMatches({ competitionId: match.competitionId, teamId: match.away?.footballDataId || match.away?.id, before: match.kickoffUtc, limit: 10 })
          .catch(() => ({ matches: [] })),
      ]);
      const currentSeasonStarted = arrayFrom(standings?.tables?.total).some((row) => Number(row.playedGames) > 0);
      const contextStandings = currentSeasonStarted ? standings : previousStandings;
      const contextMatches = uniqueMatchesById([
        ...data.matches,
        ...arrayFrom(homeRecent.matches),
        ...arrayFrom(awayRecent.matches),
      ]);
      const competition = getCompetition(match.competitionId);
      const historicalReplayState = match.finished && competition
        ? replayMatchBeforeKickoff({ matches: data.matches, match, competition })
        : null;
      const leagueContext = historicalReplayState?.context
        || buildLeagueContext({ match, standings: contextStandings, matches: contextMatches });
      leagueContext.standingSeason = currentSeasonStarted ? match.season : Number(match.season) - 1;
      leagueContext.crossSeasonForm = !currentSeasonStarted;
      const leagueAdjustment = historicalReplayState?.adjustment || deriveLeagueModelAdjustment(
        leagueContext,
        competition?.modelProfile,
      );
      let [weather, elevation, research, sporttery, odds] = quick
        ? await Promise.all([
            Promise.resolve(buildClimateWeatherFallback(geo, match.dateInfo, venue, "快速模式先使用场馆城市气候兜底，深度分析会刷新实时天气")),
            Promise.resolve({ available: false, meters: null, message: "快速模式跳过海拔抓取，后台深度分析会补充" }),
            buildResearch(match, venue, { quick: true }).catch((error) => fallbackResearch(match, error)),
            Promise.resolve(unavailableSporttery("快速模式跳过体彩慢接口，深度分析会继续补齐")),
            Promise.resolve({ enabled: false, available: false, message: "快速模式跳过外部赔率 API", markets: [] }),
          ])
        : await Promise.all([
            getWeather(geo, match.dateInfo, venue).catch((error) =>
              buildClimateWeatherFallback(geo, match.dateInfo, venue, `天气抓取失败：${error.message}`)
            ),
            getElevation(geo).catch((error) => ({ available: false, meters: null, message: `海拔抓取失败：${error.message}` })),
            buildResearch(match, venue, { depth }).catch((error) => fallbackResearch(match, error)),
            withTimeout(
              getSportteryContext(match),
              FULL_SPORTTERY_TIMEOUT_MS,
              unavailableSporttery("体彩官方接口响应超时，保留其他推荐并在缓存刷新时补齐")
            ).catch((error) => unavailableSporttery(`体彩官方接口抓取失败：${error.message}`)),
            fetchOdds(match, oddsKey).catch((error) => ({ enabled: Boolean(oddsKey), available: false, message: `赔率抓取失败：${error.message}`, markets: [] })),
          ]);

      if (historicalReplayState) {
        research = fallbackResearch(match, new Error("完场复盘不读取赛后新闻与赛后盘口"));
        odds = { enabled: false, available: false, message: "完场复盘使用逐场赛前模型，不读取赛后赔率", markets: [] };
        sporttery = unavailableSporttery("完场复盘不把赛后体彩数据当作赛前信息");
      }

      research.leagueContext = leagueContext;
      research.leagueAdjustment = leagueAdjustment;
      const forecast = await forecastService.forecast({
        match,
        liveMatches: data.matches,
        odds: historicalReplayState ? null : odds,
      }).catch((error) => {
        console.warn("forecast failed:", error.message);
        return null;
      });
      const prediction = buildPrediction({ match, venue, geo, weather, elevation, research, odds, sporttery, leagueContext, leagueAdjustment, scoreCalibration: scoreCalibrationState.profile, forecast });
      const historicalReplay = historicalReplayState
        ? buildHistoricalReplayPayload(historicalReplayState, match, findPredictionHistoryRecord(match))
        : null;
      const dataChecks = buildDataChecks({ match, venue, geo, weather, elevation, research, odds, prediction });

      return {
        refreshedAt: new Date().toISOString(),
        mode: quick ? "quick" : "full",
        match,
        venue,
        geo,
        weather,
        elevation,
        research,
        odds,
        sporttery,
        standings,
        leagueContext,
        prediction,
        forecast: forecast ? { ...forecast, rawMatrix: undefined } : null,
        historicalReplay,
        dataChecks,
        scoreCalibration: publicScoreCalibrationState(),
        dataSources: [
        {
          name: "football-data.org",
          url: `${FOOTBALL_DATA_API}/competitions/${getCompetition(match.competitionId)?.footballDataCode || "PL"}/matches?season=${match.season}`,
          note: "主赛程、球队、名单、教练、比赛状态",
        },
        {
          name: "联赛积分榜",
          url: `${FOOTBALL_DATA_API}/competitions/${getCompetition(match.competitionId)?.footballDataCode || "PL"}/standings?season=${match.season}`,
          note: "总榜、主场榜、客场榜与俱乐部赛季排名",
        },
        {
          name: "联赛场馆与赛程地点",
          url: `${FOOTBALL_DATA_API}/matches/${encodeURIComponent(match.sourceIds?.footballData || match.footballData?.id || "")}`,
          note: "比赛场馆、城市和北京时间补充",
        },
        {
          name: "Open-Meteo",
          url: "https://open-meteo.com/",
          note: "逐小时天气预报、海拔接口",
        },
        {
          name: "OpenStreetMap Nominatim",
          url: "https://nominatim.openstreetmap.org/",
          note: "球场/城市地理编码",
        },
        {
          name: "Bing News RSS / Search",
          url: "https://www.bing.com/news/search",
          note: "阵容、伤停、预测、盘口网页新闻与摘要抓取",
        },
        {
          name: "ESPN Soccer API",
          url: `${ESPN_API_ROOT}/${getCompetition(match.competitionId)?.espnSlug || "eng.1"}/scoreboard`,
          note: "赛事确认、近期状态、DraftKings 盘口摘要、官方比赛链接",
        },
        {
          name: "中国体彩网/竞彩网 Sporttery",
          url: SPORTTERY_PAGE,
          note: sporttery?.available ? "胜平负、让球胜平负、比分、总进球数官方固定奖金" : sporttery?.message || "暂无体彩官方数据",
        },
        {
          name: "Pinnacle 五大联赛 直连接口",
          url: `${PINNACLE_GUEST_API}/sports/29/leagues`,
          note: "五大联赛比赛、角球特殊盘、Bookings/罚牌特殊盘、全场 total/spread 盘口线",
        },
        {
          name: "TheSportsDB",
          url: "https://www.thesportsdb.com/api.php",
          note: "球队资料、赛事海报、比赛元数据",
        },
        {
          name: "The Odds API",
          url: "https://the-odds-api.com/",
          note: odds.enabled
            ? `已用 API Key 拉取赔率；请求市场 ${odds.marketsRequested || ODDS_API_CORE_MARKETS}${odds.warning ? `；${odds.warning}` : ""}`
            : "未配置 API Key，仅展示网页抓取参考",
        },
        ...GLOBAL_BETTING_SOURCE_CATALOG.map((source) => {
          const primaryDomain = source.domains.find((domain) => /^[a-z0-9.-]+\.[a-z]{2,}/i.test(domain));
          return {
            name: source.label,
            url: primaryDomain ? `https://${primaryDomain}` : "",
            note: `${source.category}；覆盖 ${source.markets.join("、")}`,
          };
        }),
      ],
      };
    });

    if (!prefetch) {
      recordPrediction(payload.match, payload.prediction, {
        source: quick ? "赛前快照（快速）" : "赛前分析",
        quick,
      });
    }

    res.json(payload);
  } catch (error) {
    res.status(502).json(errorPayload(error, "分析失败"));
  }
});

